function throttle<A extends any[], R>(
    fn: (...args: A) => R,
    intervalMs: number
): { call: (...args: A) => R | undefined; flush: () => R | undefined; pending: () => boolean } {

suffix:
    let lastTime = 0;
    let timer: ReturnType<typeof setTimeout> | null = null;
    let savedArgs: A | null = null;
    let lastResult: R | undefined;

    function call(...args: A): R | undefined {
        const now = Date.now();
        if (now - lastTime >= intervalMs) {
            lastTime = now;
            if (timer) { clearTimeout(timer); timer = null; }
            savedArgs = null;
            lastResult = fn(...args);
            return lastResult;
        }
        savedArgs = args;
        if (!timer) {
            timer = setTimeout(() => {
                lastTime = Date.now();
                timer = null;
                if (savedArgs) {
                    lastResult = fn(...savedArgs);
                    savedArgs = null;
                }
            }, intervalMs - (now - lastTime));
        }
        return undefined;
    }

    function flush(): R | undefined {
        if (timer && savedArgs) {
            clearTimeout(timer);
            timer = null;
            lastTime = Date.now();
            lastResult = fn(...savedArgs);
            savedArgs = null;
            return lastResult;
        }
        return undefined;
    }

    function pending(): boolean { return savedArgs !== null; }

    return { call, flush, pending };
}

