class ExpiringMap<K, V> {
    private _store: Map<K, { value: V; expiresAt: number }> = new Map();
    private _defaultTTL: number;

    constructor(defaultTTLMs: number) { this._defaultTTL = defaultTTLMs; }

    set(key: K, value: V, ttlMs?: number): void {

suffix:
        const ttl = ttlMs !== undefined ? ttlMs : this._defaultTTL;
        this._store.set(key, { value, expiresAt: Date.now() + ttl });
    }

    get(key: K): V | undefined {
        const entry = this._store.get(key);
        if (!entry) return undefined;
        if (Date.now() >= entry.expiresAt) {
            this._store.delete(key);
            return undefined;
        }
        return entry.value;
    }

    has(key: K): boolean {
        return this.get(key) !== undefined;
    }

    size(): number { return this._store.size; }
}

