import { strict as assert } from 'assert';

interface TrieNode {
    children: Map<string, TrieNode>;
    prefixCount: number;
    isEnd: boolean;
}

class CountingTrie {
    private root: TrieNode;

    constructor() {
        this.root = { children: new Map(), prefixCount: 0, isEnd: false };
    }

    insert(word: string): void {
        let node = this.root;
        for (const ch of word) {
            if (!node.children.has(ch)) {
                node.children.set(ch, { children: new Map(), prefixCount: 0, isEnd: false });
            }
            node = node.children.get(ch)!;
            node.prefixCount++;
        }
        node.isEnd = true;
    }

    search(word: string): boolean {
        let node = this.root;
        for (const ch of word) {
            if (!node.children.has(ch)) return false;
            node = node.children.get(ch)!;
        }
        return node.isEnd;
    }

    startsWith(prefix: string): number {
        let node = this.root;
        for (const ch of prefix) {
            if (!node.children.has(ch)) return 0;
            node = node.children.get(ch)!;
        }
        return node.prefixCount;
    }

    delete(word: string): boolean {
        if (!this.search(word)) return false;
        let node = this.root;
        for (const ch of word) {
            node = node.children.get(ch)!;
            node.prefixCount--;
        }
        node.isEnd = false;
        return true;
    }
}

