const timestamps: number[] = [];
const burstWindowMs = 100;

return {
    tryAcquire(): RateLimitResult {
        const now = Date.now();
        // Remove expired timestamps
        while (timestamps.length > 0 && timestamps[0] <= now - windowMs) {
            timestamps.shift();
        }

        // Check burst window: count requests in last 100ms
        const burstLimit = Math.floor(maxRequests * burstMultiplier);
        const burstStart = now - burstWindowMs;
        const recentCount = timestamps.filter(t => t > burstStart).length;

        // Apply the tighter of: burst limit (for recent) or normal limit (for window)
        if (timestamps.length >= maxRequests || recentCount >= burstLimit) {
            const retryAfter = timestamps[0] + windowMs - now;
            return { allowed: false, retryAfter: Math.max(1, retryAfter) };
        }

        timestamps.push(now);
        return { allowed: true, retryAfter: 0 };
    }
};

